          (error.message === 'Invalid tournament.' || error.message.startsWith('Unknown field:'))
        ),
    };
  }
}
function encode(tournament: TournamentState | null, snapshot: string | null): string {
  // Object keys are alphabetical at every level, including nested snapshots.
  const sort = (_key: string, value: unknown): unknown =>
    isJsonObject(value)
      ? Object.fromEntries(Object.entries(value).sort(([a], [b]) => a.localeCompare(b)))
      : value;
  return JSON.stringify(
    { format: 'neon-pairs/tournament', snapshot, tournament, version: 1 },
    sort,
    2,
  );
}
function decode(text: string): { tournament: TournamentState | null; snapshot: string | null } {
  if (new TextEncoder().encode(text).length > 65536) throw new Error('Invalid tournament.');
  const value: unknown = JSON.parse(text);
  if (!isJsonObject(value)) throw new Error('Invalid tournament.');
  const extra = Object.keys(value).find(
    (key) => !['format', 'snapshot', 'tournament', 'version'].includes(key),
  );
  if (extra) throw new Error(`Unknown field: ${extra}.`);
  if (
    Object.keys(value).length !== 4 ||
    value.format !== 'neon-pairs/tournament' ||
    value.version !== 1
  )
    throw new Error('Invalid tournament.');
  const tournament = value.tournament === null ? null : validateTournament(value.tournament);
  if (value.snapshot !== null && typeof value.snapshot !== 'string')
    throw new Error('Invalid tournament.');
  if ((tournament?.phase === 'playing') !== (typeof value.snapshot === 'string'))
    throw new Error('Invalid tournament.');
  if (typeof value.snapshot === 'string') {
    const game = decodeSnapshot(value.snapshot);
    if (!game || isWon(game) || game.boardCode !== tournament?.matches.at(-1)?.boardCode)
      throw new Error('Invalid tournament.');
  }
  return { tournament, snapshot: value.snapshot as string | null };
}
function fresh(t: TournamentState): string {
  const size = roundFor(t.names.length, t.matches.length).size;
  let code: string;
  do {
    code = freshBoardCode(size);
  } while (t.matches.some((match) => match.boardCode === code));
  return code;
}

export function Tournament({ back }: { back(): void }) {
  const controller = useGame(true);
  const [count, setCount] = useState(4);
  const [names, setNames] = useState<string[]>(Array(8).fill(''));
  const [tournament, setTournament] = useState<TournamentState | null>(null);
  const [json, setJson] = useState('');
  const [notice, setNotice] = useState('');
  const [history, setHistory] = useState(readHistory);
  const heading = useRef<HTMLHeadingElement>(null);
  const board = useRef<BoardFocus>(null);
  const dialog = useRef<HTMLDialogElement>(null);
  const keep = useRef<HTMLButtonElement>(null);
  const pending = useRef<(() => void) | null>(null);
  const recorded = useRef(false);
  useEffect(() => {
    heading.current?.focus();
  }, []);
  const match = tournament?.matches.at(-1);
  const player = match?.results[0] ? 1 : 0;
  useEffect(() => {
    if (
      !tournament ||
      tournament.phase !== 'playing' ||
      !isWon(controller.session.game) ||
      recorded.current
    )
      return;
    recorded.current = true;
    const updated = recordResult(tournament, {
      moves: controller.session.game.moves,
      elapsedMs: controller.session.game.elapsedMs,
    });
    setTournament(updated);
    if (updated.phase === 'complete') {
      setHistory((old) => {
        const items = [updated, ...old.items].slice(0, 10);
        try {
          localStorage.setItem(KEY, JSON.stringify({ v: 3, items }));
          return { items, unavailable: false };
        } catch {
          return { items, unavailable: true };
        }
      });
    }
  }, [controller.session.game, tournament]);
  function askLeave(action: () => void) {
    if (tournament && tournament.phase !== 'complete') {
      pending.current = action;
      dialog.current?.showModal();
      keep.current?.focus();
    } else action();
  }
  function start() {
    const accepted = names.slice(0, count).map(normalizeName);
    const error = nameError(accepted);
    if (error) {
      setNotice(error);
      return;
    }
    const initial: TournamentState = { names: accepted, matches: [], phase: 'ready' };
    setTournament(nextMatch(initial, fresh(initial)));
    setNotice('');
  }
  function begin() {
    if (!match) return;
    recorded.current = false;
    controller.loadBoard(match.boardCode);
    setTournament((old) => (old ? { ...old, phase: 'playing' } : old));
    setNotice('');
  }
  function advance() {
    if (!tournament) return;
    if (tournament.phase === 'turnEnd') setTournament({ ...tournament, phase: 'ready' });
    else setTournament(nextMatch(tournament, fresh(tournament)));
    setNotice('');
  }
  function load() {
    try {
      const decoded = decode(json);
      const apply = () => {
        if (decoded.snapshot) controller.loadSnapshot(decoded.snapshot);
        recorded.current = false;
        setTournament(decoded.tournament);
        setNotice('Tournament loaded.');
      };
      askLeave(apply);
    } catch (error) {
      setNotice(
        error instanceof Error && error.message.startsWith('Unknown field:')
          ? error.message
          : 'Invalid tournament.',
      );
    }
  }
  const status =
    notice ||
    (tournament && match
      ? tournament.phase === 'complete'
        ? `Champion: ${tournament.names[match.winner!]}`
        : `Now playing: ${tournament.names[match.players[player]]}`
      : '');
  return (
    <main className="tournament">
      <header>
        <p className="eyebrow">A little focus. A perfect pair.</p>
        <h1>Neon Pairs</h1>
      </header>
      <h2 ref={heading} tabIndex={-1}>
        Tournament
      </h2>
      <div className="game-result">
        <p role="status" aria-live="polite" aria-atomic="true">
          <span key={notice || controller.session.announcement}>
            {notice ||
              (tournament?.phase === 'playing' && controller.session.feedback
                ? controller.session.feedback
                : status)}
          </span>
        </p>
      </div>
      {!tournament ? (
        <>
          <div className="tournament-form">
            <label htmlFor="players">Players</label>
            <select
              className="control"
              id="players"
              value={count}
              onChange={(e) => setCount(Number(e.target.value))}
            >
              <option value={4}>4</option>
              <option value={8}>8</option>
            </select>
            {names.slice(0, count).map((name, index) => (
              <div className="name-field" key={index}>
                <label htmlFor={`player-${index}`}>Player {index + 1}</label>
                <input
                  className="control"
                  id={`player-${index}`}
                  value={name}
                  onChange={(e) =>
                    setNames((old) => old.map((n, i) => (i === index ? e.target.value : n)))
                  }
                />
              </div>
            ))}
            <button className="control" type="button" onClick={start}>
              Start tournament
            </button>
          </div>
          <h3>Past tournaments</h3>
          {history.unavailable && <p>Progress won't be saved on this device.</p>}
          {history.items.length === 0 ? (
            <p>No past tournaments.</p>
          ) : (
            <ul>
              {history.items.map((item, index) => (
                <li key={index}>
                  <button
                    type="button"
                    className="control"

                  onChange={(e) =>
                    setNames((old) => old.map((n, i) => (i === index ? e.target.value : n)))
                  }
                />
              </div>
            ))}
            <button className="control" type="button" onClick={start}>
              Start tournament
            </button>
          </div>
          <h3>Past tournaments</h3>
          {history.unavailable && <p>Progress won't be saved on this device.</p>}
          {history.items.length === 0 ? (
            <p>No past tournaments.</p>
          ) : (
            <ul>
              {history.items.map((item, index) => (
                <li key={index}>
                  <button
                    type="button"
                    className="control"
                    onClick={() => {
                      setTournament(item);
                      setNotice('');
                    }}
                  >
                    Champion: {item.names[item.matches.at(-1)!.winner!]}
                  </button>
                </li>
              ))}
            </ul>
          )}
          <button type="button" className="control" onClick={back}>
            Back to game
          </button>
        </>
      ) : (
        <>
          {match && tournament.phase !== 'complete' && (
            <>
              <p>Round: {roundFor(tournament.names.length, tournament.matches.length - 1).name}</p>
              <p>Now playing: {tournament.names[match.players[player]]}</p>
            </>
          )}
          {tournament.phase === 'complete' && match && (
            <h3>Champion: {tournament.names[match.winner!]}</h3>
          )}
          <div className="tournament-actions">
            {tournament.phase === 'ready' && (
              <button className="control" type="button" onClick={begin}>
                Start turn
              </button>
            )}
            {tournament.phase === 'turnEnd' && (
              <button className="control" type="button" onClick={advance}>
                Next turn
              </button>
            )}
            {tournament.phase === 'matchEnd' && (
              <button className="control" type="button" onClick={advance}>
                Next match
              </button>
            )}
            {tournament.phase === 'complete' ? (
              <button className="control" type="button" onClick={back}>
                Back to game
              </button>
            ) : (
              <button className="control" type="button" onClick={() => askLeave(back)}>
                Leave tournament
              </button>
            )}
          </div>
          {tournament.phase === 'playing' && (
            <>
              <GameStatus
                game={controller.session.game}
                best={undefined}
                celebration={controller.session.celebration}
              />
              {controller.session.paused && (
                <button
                  className="control"
                  onClick={() => {
                    board.current?.focusRemembered();
                    controller.resume();
                  }}
                >
                  Resume
                </button>
              )}
              <p id="board-help" className="help">
                Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or
                Space reveals a card.
              </p>
              <Board
                key={controller.session.generation}
                game={controller.session.game}
                activate={controller.activate}
                ref={board}
              />
            </>
          )}
          <div className="bracket">
            <table>
              <caption>Bracket</caption>
              <thead>
                <tr>
                  <th scope="col">Round</th>
                  <th scope="col">Player 1</th>
                  <th scope="col">Moves</th>
                  <th scope="col">Time</th>
                  <th scope="col">Player 2</th>
                  <th scope="col">Moves</th>
                  <th scope="col">Time</th>
                  <th scope="col">Winner</th>
                </tr>
              </thead>
              <tbody>
                {Array.from({ length: tournament.names.length - 1 }, (_, index) => {
                  const entry = tournament.matches[index];
                  const pair =
                    entry?.players ??
                    playersFor(tournament, index) ??
                    opening(tournament.names.length)[index];
                  return (
                    <tr key={index}>
                      <td>{roundFor(tournament.names.length, index).name}</td>
                      <td>{pair ? tournament.names[pair[0]] : 'TBD'}</td>
                      <td>{entry?.results[0]?.moves ?? '—'}</td>
                      <td>{entry?.results[0] ? formatElapsed(entry.results[0].elapsedMs) : '—'}</td>
                      <td>{pair ? tournament.names[pair[1]] : 'TBD'}</td>
                      <td>{entry?.results[1]?.moves ?? '—'}</td>
                      <td>{entry?.results[1] ? formatElapsed(entry.results[1].elapsedMs) : '—'}</td>
                      <td>{entry?.winner != null ? tournament.names[entry.winner] : '—'}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </>
      )}
      <section className="tournament-exchange">
        <h3>Share tournament</h3>
        <label htmlFor="tournament-json">Tournament JSON</label>
        <textarea
          className="control"
          id="tournament-json"
          rows={8}
          value={json}
          onChange={(e) => setJson(e.target.value)}
        />
        <div className="tournament-actions">
          <button
            className="control"
            type="button"
            onClick={() => {
              setJson(
                encode(
                  tournament,
                  tournament?.phase === 'playing' ? controller.exportSnapshot() : null,
                ),
              );
              setNotice('Tournament exported.');
            }}
          >
            Export tournament
          </button>
          <button className="control" type="button" onClick={load}>
            Load tournament
          </button>
        </div>
      </section>
      <dialog
        ref={dialog}
        onCancel={(e) => {
          e.preventDefault();
          dialog.current?.close();
          pending.current = null;
        }}
      >
        <p>Leave this unfinished tournament?</p>
        <div className="tournament-actions">
          <button
            ref={keep}
            className="control"
            onClick={() => {
              dialog.current?.close();
              pending.current = null;
            }}
          >
            Keep playing
          </button>
          <button
            className="control"
            onClick={() => {
              dialog.current?.close();
              const action = pending.current;
              pending.current = null;
              action?.();
            }}
          >
            Leave
          </button>
        </div>
      </dialog>
    </main>
  );
}

