      t = nextMatch(t, `np1-6-${i + 1}`);
      t = recordResult(t, { moves: 18, elapsedMs: 10 });
      t = recordResult(t, { moves: 19, elapsedMs: 10 });
    }
    t = nextMatch(t, 'np1-8-3');
    t = recordResult(t, { moves: 33, elapsedMs: 10 });
    t = { ...t, phase: 'ready' };
    await page.getByLabel('Tournament JSON').fill(
      JSON.stringify({
        format: 'neon-pairs/tournament',
        snapshot: null,
        tournament: t,
        version: 1,
      }),
    );
    await page.getByRole('button', { name: 'Load tournament' }).click();
    await page.getByRole('button', { name: 'Start turn' }).click();
    await solve(page, 'np1-8-3');
    await expect(page.getByRole('heading', { name: 'Champion: Bea' })).toBeVisible();
    await expect(page.getByRole('table', { name: 'Bracket' })).toBeVisible();
    await page.reload();
    await expect(page.getByLabel('Size')).toHaveValue('10');
    await page.getByRole('button', { name: 'Tournament', exact: true }).click();
    await page.getByRole('button', { name: 'Champion: Bea' }).click();
    await expect(page.getByRole('heading', { name: 'Champion: Bea' })).toBeVisible();
    expect((await exported(page)).tournament.phase).toBe('complete');
  },
  {},
  undefined,
  TestTimeouts.long,

          className="control"
          id="players"
          value={count}
          onChange={(e) => setCount(Number(e.target.value))}
        >
          <option value={4}>4</option>
          <option value={8}>8</option>
        </select>
        {names.slice(0, count).map((name, index) => (
          <div className="name-field" key={index}>
            <label htmlFor={`player-${index}`}>Player {index + 1}</label>
            <input
              className="control"
              id={`player-${index}`}
              value={name}
              onChange={(e) =>
                setNames((old) => old.map((n, i) => (i === index ? e.target.value : n)))
              }
            />
          </div>
        ))}
        {(notice === 'Use 2 to 20 characters.' || notice === 'Each name must be different.') && (
          <p id="name-notice">{notice}</p>
        )}
        <button className="control" type="button" onClick={start} aria-describedby="name-notice">
          Start tournament
        </button>
      </div>
      <h3>Past tournaments</h3>
      {history.unavailable && <p>Progress won't be saved on this device.</p>}
      {history.items.length === 0 ? (
        <p>No past tournaments.</p>
      ) : (
        <ul>
          {history.items.map((item, index) => (
            <li key={index}>
              <button type="button" className="control" onClick={() => open(item)}>
                Champion: {item.names[item.matches.at(-1)!.winner!]}
              </button>
            </li>
          ))}
        </ul>
      )}
      <button type="button" className="control" onClick={back}>
        Back to game
      </button>
    </>
  );
}
